#!/usr/bin/env node
// The typed SignalR client on the client's own models: node signalr-models.mjs <tsrts output> <openapi.json> <destination>
//
// TypedSignalR.Client.TypeScript (dotnet tsrts) writes the hubs' proxies and receivers (TypedSignalR.Client/*.ts), and
// Tapper writes the DTOs they use, a file per C# namespace (GrifballWebApp.Application.Teams.ts), which the proxies
// import. This copies the proxies and receivers as they are and writes each namespace's file as a re-export of the
// models generated from openapi.json (@api/models): one set of DTOs for REST and SignalR. A DTO's model is its schema of
// the same name or, where two of the app's types share a name, the one with its namespace's last segment in front
// (TeamsPlayerDto: the server's OpenApiSchemaIds). A DTO with neither fails: the document lacks it.
import { copyFileSync, mkdirSync, readdirSync, readFileSync, realpathSync, rmSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';

const HEADER = '/* eslint-disable */\n/* Code generated by .github/scripts/signalr-models.mjs DO NOT EDIT. */\n';
const PROXIES = 'TypedSignalR.Client';

/** The types a Tapper file exports. */
export function exportedTypes(source) {
  return [...source.matchAll(/^export (?:type|enum|interface|class) (\w+)/gm)].map(m => m[1]);
}

/** A DTO's model name: its own, else its namespace's last segment in front; null when the document has neither. */
export function modelName(namespace, type, schemas) {
  if (type in schemas)
    return type;
  const qualified = namespace.slice(namespace.lastIndexOf('.') + 1) + type;
  return qualified in schemas ? qualified : null;
}

/** A namespace file re-exporting its DTOs' models, or the names the document lacks. */
export function reexport(namespace, types, schemas) {
  const missing = types.filter(t => modelName(namespace, t, schemas) === null);
  if (missing.length)
    return { missing };
  const names = types.map(t => { const model = modelName(namespace, t, schemas); return model === t ? t : `${model} as ${t}`; });
  return { source: `${HEADER}\n// ${namespace}'s DTOs: the client's models (openapi.json), the ones its REST services use\nexport type { ${names.join(', ')} } from '@api/models';\n` };
}

function main([output, openapi, destination]) {
  const schemas = JSON.parse(readFileSync(openapi, 'utf8')).components.schemas;
  rmSync(destination, { recursive: true, force: true });
  mkdirSync(join(destination, PROXIES), { recursive: true });
  for (const file of readdirSync(join(output, PROXIES)).filter(f => f.endsWith('.ts')))
    copyFileSync(join(output, PROXIES, file), join(destination, PROXIES, file));

  const lacking = [];
  for (const file of readdirSync(output).filter(f => f.endsWith('.ts'))) {
    const namespace = file.slice(0, -'.ts'.length);
    const { source, missing } = reexport(namespace, exportedTypes(readFileSync(join(output, file), 'utf8')), schemas);
    if (missing)
      lacking.push(...missing.map(t => `${namespace}.${t}`));
    else
      writeFileSync(join(destination, file), source);
  }
  if (lacking.length) {
    console.error(`::error title=SignalR DTOs not in openapi.json::${lacking.join(', ')}: give the server's document their schemas (HubSchemasDocumentFilter)`);
    process.exit(1);
  }
}

// Run directly (not imported): its real path as a file URL spells it, spaces and drive letters included; the real
// path, not argv[1] as given, so running through a symlink (to the script, or to its directory) still matches
// import.meta.url, which Node resolves to the real path too
if (process.argv[1] && import.meta.url === pathToFileURL(realpathSync(process.argv[1])).href)
  main(process.argv.slice(2));
